// 1. 在这里填入你需要的 RSSHub 订阅源 (加上 ?format=json)
return [
  { json: { url: "https://rss.xujwx.xyz/cls/telegraph?format=json", name: "财联社" } },
  { json: { url: "https://rss.xujwx.xyz/wallstreetcn/live/global?format=json", name: "华尔街见闻" } }
];

const hoursAgo = 12;
const cutoffTime = new Date(new Date().getTime() - hoursAgo * 60 * 60 * 1000);
const allFeeds = $input.all();
let allItems = [];

for (const feed of allFeeds) {
  let sourceData = feed.json.data || feed.json.items || feed.json;
  if (typeof sourceData === 'string') {
    try { sourceData = JSON.parse(sourceData); } 
    catch (e) { continue; }
  }

  const items = Array.isArray(sourceData) ? sourceData : (sourceData.items || []);
  if (!Array.isArray(items)) continue;

  for (const item of items) {
    const timeString = item.date_published || item.pubDate || item.created_at || item.time;
    const itemTime = new Date(timeString);

    if (!isNaN(itemTime.getTime()) && itemTime > cutoffTime) {
      // 提取内容并剔除 HTML 标签，防止 AI token 爆炸
      let rawContent = item.summary || item.content_html || item.description || "";
      let cleanContent = rawContent.replace(/<[^>]+>/g, '').substring(0, 300);

      allItems.push({
        title: item.title || "无标题",
        content: cleanContent,
        url: item.url || item.link || "",
        time: itemTime.toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' })
      });
    }
  }
}

// 简单去重
const uniqueMap = new Map();
for (const item of allItems) {
  if (item.title && !uniqueMap.has(item.title)) {
    uniqueMap.set(item.title, item);
  }
}
const uniqueItems = Array.from(uniqueMap.values());

// 打包成一个整体输出
return { 
  json: { 
    news_list: uniqueItems, 
    total_count: uniqueItems.length 
  } 
};
